'use client';
import {useEffect,useState} from 'react';
import Link from 'next/link';
import {Plus,Search,SlidersHorizontal,ChevronRight,FileText,RefreshCw} from 'lucide-react';
import {request} from '@/lib/client';
import {CATEGORIES,STATUSES,DISTRICTS} from '@/lib/constants';
import {Status,ErrorBox,Loading,Empty} from './city-ui';
import {SafeDate} from './safe-format';
export default function TicketList({admin,initialQuery=''}:{admin:boolean;initialQuery?:string}){const [tickets,setTickets]=useState<any[]>([]);const [status,setStatus]=useState('');const [category,setCategory]=useState('');const [district,setDistrict]=useState('');const [query,setQuery]=useState(initialQuery);const [error,setError]=useState('');const [loading,setLoading]=useState(true);const [reload,setReload]=useState(0);
 useEffect(()=>{let live=true;setLoading(true);const timer=setTimeout(()=>{const params=new URLSearchParams({status,category,district,q:query});request(`/api/tickets?${params}`).then((data:any)=>{if(live){setTickets(data??[]);setError('');}}).catch((e:Error)=>{console.error(e);if(live)setError(e.message);}).finally(()=>{if(live)setLoading(false);});},250);return()=>{live=false;clearTimeout(timer);};},[status,category,district,query,reload]);
 return <div><div className="mb-7 flex flex-wrap justify-between gap-4"><div><h1 className="page-title">{admin?'Başvuru yönetimi':'Başvurularım'}</h1><p className="mt-2 text-sm text-muted-foreground">{admin?'Başvuruları inceleyin, ilgili birimlerin sürecini yönetin ve yanıtlayın.':'Şehrin için attığın adımları ve çözüm sürecini takip et.'}</p></div><Link href="/basvuru/yeni" className="btn self-start"><Plus size={16}/>Yeni başvuru</Link></div><div className="panel p-5"><div className="mb-5 flex flex-wrap items-center gap-3"><div className="relative min-w-[180px] flex-1"><Search size={16} className="absolute left-3 top-3.5 text-muted-foreground"/><input aria-label="Başlık veya başvuru numarasıyla ara" value={query} onChange={(e)=>setQuery(e.target.value)} className="pl-9" placeholder="Başlık veya başvuru numarası ara…"/></div><SlidersHorizontal size={18} className="hidden text-muted-foreground md:block"/><select aria-label="Duruma göre filtrele" value={status} onChange={(e)=>setStatus(e.target.value)} className="w-auto"><option value="">Tüm durumlar</option>{Object.entries(STATUSES).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select><select aria-label="Kategoriye göre filtrele" value={category} onChange={(e)=>setCategory(e.target.value)} className="w-auto"><option value="">Tüm kategoriler</option>{Object.entries(CATEGORIES).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select>{admin&&<select aria-label="İlçeye göre filtrele" value={district} onChange={(e)=>setDistrict(e.target.value)} className="w-auto"><option value="">Tüm ilçeler</option>{DISTRICTS.map((d)=><option key={d}>{d}</option>)}</select>}<button onClick={()=>setReload((v)=>v+1)} className="btn-light !px-3" aria-label="Listeyi yenile"><RefreshCw size={16}/></button></div><ErrorBox message={error}/>{loading?<Loading/>:tickets.length?<div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead className="bg-muted text-[10px] text-muted-foreground"><tr>{['BAŞVURU','KATEGORİ','İLÇE','TARİH','DURUM',''].map((h)=><th key={h} className="whitespace-nowrap px-3 py-3 font-medium">{h}</th>)}</tr></thead><tbody>{tickets.map((t:any)=><tr key={t.id} className="border-b border-border/60 last:border-0 hover:bg-muted/40"><td className="max-w-[260px] px-3 py-5"><Link className="block truncate font-semibold text-foreground hover:text-primary" href={`/basvurular/${t.id}`}>{t.title}</Link><span className="mt-1.5 block font-mono text-[9px] text-muted-foreground">#{t.id?.slice(0,8).toUpperCase()}</span></td><td className="whitespace-nowrap px-3">{CATEGORIES[t.category]}</td><td className="px-3">{t.district}</td><td className="whitespace-nowrap px-3 text-muted-foreground"><SafeDate date={t.createdAt} locale="tr-TR" options={{day:'numeric',month:'short',year:'numeric'}}/></td><td className="px-3"><Status value={t.status}/></td><td className="px-3"><Link aria-label={`${t.title} detaylarını gör`} href={`/basvurular/${t.id}`} className="inline-flex rounded-md bg-muted p-2"><ChevronRight size={14}/></Link></td></tr>)}</tbody></table><p className="mt-4 text-[10px] text-muted-foreground">{tickets.length} başvuru gösteriliyor · En güncel 200 kayıt</p></div>:<Empty title="Başvuru bulunamadı" description="Henüz bir başvurun olmayabilir veya seçtiğin filtrelerle eşleşen kayıt bulunmuyor."/>}</div></div>;
}
